   "id": "z6243a6af",
   "sez": "prima",
   "titolo": "Il governo impugna la legge del Veneto sul fine vita",
   "orig": "Il governo impugna la legge del Veneto sul Fine vita, Zaia: 'Rispetto, ma rivendico la scelta'",
   "lead": "Il Consiglio dei ministri ha deciso di impugnare dinanzi alla Corte costituzionale la legge regionale del Veneto che disciplina procedure e tempi per l'accesso al fine vita. Durante la riunione, il segretario della Lega Matteo Salvini non ha partecipato alla discussione e non ha espresso il proprio voto. Il presidente della Regione Luca Zaia ha dichiarato di rispettare la scelta del governo pur rivendicando la bontà del testo approvato. Il ministro Antonio Tajani ha ricordato che occorre un intervento organico del Parlamento nazionale.",
   "more": [
    "In assenza di una legge quadro statale, la Corte costituzionale ha stabilito criteri precisi per la non punibilità dell'aiuto al suicidio medicalmente assistito. Alcune Regioni hanno tentato di colmare il vuoto normativo regolando le tempistiche sanitarie, ma il governo centrale ritiene la materia di esclusiva competenza statale."
   ],
