   "id": "z12a6086c",
   "sez": "cultura",
   "titolo": "Pierpaolo Piccioli lascia la direzione creativa della maison Balenciaga",
   "orig": "Pierpaolo Piccioli lascia la direzione creativa di Balenciaga",
   "lead": "Lo stilista italiano Pierpaolo Piccioli ha annunciato la decisione di lasciare la guida creativa della casa di moda Balenciaga. La notizia giunge a un solo mese di distanza dall'addio di Anthony Vaccarello al marchio Yves Saint Laurent, altra importante griffe controllata dal gruppo francese del lusso Kering. L'avvicendamento segna una nuova tappa nella fase di profonda riorganizzazione delle direzioni artistiche che sta interessando alcuni dei più prestigiosi marchi dell'alta moda a livello internazionale. Lo riferisce ANSA.",
   "more": [
    "I grandi conglomerati del lusso operano in un mercato altamente competitivo, dove i cicli di consumo e le strategie di immagine richiedono frequenti rinnovamenti stilistici. La sostituzione dei direttori creativi incide sul posizionamento commerciale delle collezioni e sull'attrattività globale dei marchi storici."
   ],
