   "id": "z1c64ef9b",
   "sez": "economia",
   "titolo": "Il Portogallo stanzia quaranta milioni di aiuti per gli agricoltori",
   "orig": "Governo aprova apoio de 40 milhões de euros aos agricultores face a custos dos adubos e energia",
   "lead": "Il governo del Portogallo ha approvato un piano straordinario di aiuti economici del valore complessivo di quaranta milioni di euro a supporto del settore agricolo nazionale. Il pacchetto finanziario è stato varato per compensare i produttori dalle forti impennate dei costi di approvvigionamento per fertilizzanti ed energia, conseguenze dirette dell'instabilità e dei conflitti in Medio Oriente. L'intervento mira a sostenere la redditività delle aziende agricole e a contenere i rincari che rischiano di trasferirsi lungo la filiera alimentare. Lo riferisce RTP.",
   "more": [
    "Le crisi geopolitiche nelle aree di transito energetico comportano frequenti rincari sui combustibili e sulle materie prime indispensabili per la sintesi dei fertilizzanti azotati. Senza sussidi pubblici straordinari, le aziende agricole rischiano di contrarre le produzioni o di aumentare bruscamente i prezzi al consumo."
   ],
