   "id": "z97be6b85",
   "sez": "sport",
   "titolo": "Fallisce il circuito LIV Golf dopo la rottura dei negoziati sui fondi",
   "orig": "LIV Golf to be liquidated as financing deal collapses",
   "lead": "Il circuito ribelle LIV Golf, sostenuto in precedenza dai fondi dell'Arabia Saudita, ha annunciato l'avvio della liquidazione e della progressiva cessazione delle proprie attività dopo il collasso del piano di salvataggio da trecento milioni di dollari. La competizione, nata nel 2022 con l'ingaggio milionario di stelle del golf mondiale in aperta contrapposizione al circuito tradizionale PGA Tour, è andata in crisi irreversibile in seguito al ritiro dei finanziamenti sauditi e alla recente perdita di atleti di primissimo piano.",
   "more": [
    "L'ingresso di enormi capitali sovrani nel golf professionistico aveva spaccato in due la disciplina, scatenando battaglie legali e dispute tra tornei storici e nuove leghe private. La sostenibilità economica dei circuiti indipendenti richiede introiti commerciali stabili e diritti televisivi non sempre facili da consolidare nel tempo."
   ],
