   "id": "zd3748b69",
   "sez": "ambiente",
   "titolo": "Dalle ali delle farfalle vernici ecologiche senza pigmenti chimici nocivi",
   "orig": "The butterfly effect: a brighter way to make paint?",
   "lead": "Un gruppo di ricercatori ha avviato studi sulle proprietà strutturali delle ali delle farfalle per sviluppare vernici e rivestimenti industriali colorati privi di pigmenti chimici dannosi per l'ambiente e la salute. L'approccio scientifico si ispira al modo in cui la luce viene riflessa e rifratta dalle microscopiche geometrie alari, creando tinte vivide mediante fenomeni fisici anziché attraverso additivi sintetici tossici. L'innovazione tecnologica potrebbe rivoluzionare il settore delle pitture, riducendo significativamente l'inquinamento generato dai composti chimici tradizionali. Lo riferisce Positive News.",
   "more": [
    "Il biomimetismo applica soluzioni ricavate dall'osservazione dei meccanismi naturali alla moderna ingegneria dei materiali. La produzione di colorazioni strutturali, prive di coloranti artificiali biodegradabili o inquinanti, promette finiture durevoli che non sbiadiscono e non rilasciano sostanze tossiche."
   ],
