   "id": "z1d52e7ce",
   "sez": "mondo",
   "titolo": "Lesotho, l'ex premier Majoro accusa l'ex ministro Tšolo per lo scandalo Frazer Solar",
   "orig": "Majoro pins M856m Frazer Solar scandal on Tšolo",
   "lead": "L'ex primo ministro del Lesotho, Moeketsi Majoro, ha deposto davanti all'Alta corte indicando l'ex ministro presso l'ufficio del primo ministro, Temeki Tšolo, come figura centrale nel controverso accordo Frazer Solar da 856 milioni di maloti. Majoro ha dichiarato che Tšolo ha firmato un memorandum d'intesa privo della necessaria approvazione da parte del consiglio dei ministri e in diretta violazione delle procedure finanziarie stabilite dal governo. La vicenda giudiziaria riguarda la gestione dei fondi pubblici e la legittimità dei contratti energetici stipulati dal Lesotho. Lo riferisce Lesotho Times.",
   "more": [
    "Le controversie sui grandi progetti energetici statali nei Paesi in via di sviluppo spesso coinvolgono l'arbitrato internazionale e la validità delle firme ministeriali. Quando accordi milionari vengono sottoscritti senza le approvazioni dei consigli di gabinetto, i governi successivi possono contestare la regolarità delle obbligazioni assunte per tutelare i bilanci pubblici."
   ],
