   "sez": "cultura",
   "titolo": "A Bragança quasi duecento opere della collezione Alberto Caetano in mostra",
   "orig": "Quase 200 obras da coleção Alberto Caetano no Centro de Arte Contemporânea de Bragança",
   "lead": "Il Centro de Arte Contemporânea Graça Morais di Bragança ospita a partire da oggi un'esposizione composta da quasi duecento opere appartenenti alla collezione dell'architetto e collezionista Alberto Caetano. I lavori esposti provengono da una donazione effettuata a favore del Museu Nacional de Arte Contemporânea do Chiado di Lisbona. La rassegna offre al pubblico del nord del Portogallo la possibilità di ammirare una vasta selezione di pezzi d'arte contemporanea custoditi finora dall'istituzione museale della capitale, valorizzando il patrimonio artistico donato dall'architetto. Lo riferisce RTP.",
   "more": [
    "Le donazioni di collezioni private ai musei statali costituiscono uno dei canali fondamentali per l'arricchimento del patrimonio culturale pubblico. Spesso queste raccolte vengono poi fatte circolare sul territorio nazionale tramite mostre temporanee in centri espositivi regionali, promuovendo il decentramento dell'offerta artistica oltre le città capitali."
   ],
