   "sez": "mondo",
   "titolo": "Nigeria, il JAMB accrediterà solo centri idonei per i test UTME 2027",
   "orig": "Only qualified CBT centres will host 2027 UTME — JAMB",
   "lead": "In Nigeria, il Joint Admissions and Matriculation Board ha stabilito che solo i centri per prove informatizzate che rispettano pienamente gli standard tecnici prescritti riceveranno l'accreditamento per ospitare la sessione del 2027 del Unified Tertiary Matriculation Examination. L'ente ha confermato che i rigorosi requisiti serviranno a garantire la sicurezza, l'affidabilità delle infrastrutture informatiche e il corretto svolgimento degli esami di ammissione all'istruzione terziaria in tutto il Paese, escludendo le strutture non conformi. Lo riferisce The Punch.",
   "more": [
    "L'esame UTME è la prova unificata necessaria per l'accesso a università, politecnici e college in Nigeria. Il passaggio ai test interamente svolti su computer mira a ridurre le frodi e le irregolarità, richiedendo però standard severi per la connettività, l'alimentazione elettrica e la sorveglianza delle aule d'esame."
   ],
