   "sez": "adolescenti",
   "titolo": "#ioleggoperché, l'invito di Andrea Maggi a donare libri alle scuole",
   "orig": "#ioleggoperché, Andrea Maggi: la lettura è “la palestra migliore per la mente umana”. L’invito a donare alle scuole il libro “che hai amato più di tutti”",
   "lead": "Nell'ambito dell'iniziativa #ioleggoperché, l'insegnante e scrittore Andrea Maggi ha invitato i cittadini a sostenere le biblioteche scolastiche donando un volume significativo. Definendo la lettura come la migliore palestra per la mente umana, Maggi propone a ciascuno di scegliere il libro più amato, acquistarne una copia e regalarla a una scuola, magari accompagnandola con una dedica scritta a mano sulla prima pagina. La proposta mira a diffondere l'abitudine alla lettura tra gli studenti attraverso la condivisione diretta di storie ed esperienze formative. Lo riferisce Orizzonte Scuola.",
   "more": [
    "I progetti di promozione della lettura nelle scuole incoraggiano la cittadinanza attiva e il sostegno alle strutture educative. Donare testi alle biblioteche scolastiche aiuta ad ampliare l'offerta di testi disponibili per bambini e ragazzi, favorendo lo sviluppo del pensiero critico, delle competenze linguistiche e della concentrazione."
   ],
