   "sez": "salute",
   "titolo": "Fatture sanitarie negli Stati Uniti, due arbitri perdono i contratti governativi",
   "orig": "STAT+: Two No Surprises Act arbitrators lose government contracts to decide payment disputes",
   "lead": "Negli Stati Uniti, l'amministrazione Trump ha revocato i contratti governativi a due società incaricate di arbitrare le dispute sui pagamenti sanitari previste dal No Surprises Act. Secondo quanto reso noto dalle autorità federali, la decisione è stata motivata dall'incapacità dei due gruppi di rispettare gli standard minimi di prestazione stabiliti per legge. La misura colpisce gli enti che intervengono per risolvere i contenziosi tra ospedali e assicurazioni riguardanti i conti medici imprevisti inviati ai pazienti. Lo riferisce STAT.",
   "more": [
    "Il No Surprises Act è una legge federale statunitense creata per proteggere i pazienti da fatture mediche inattese e particolarmente elevate quando ricevono cure d'urgenza o prestazioni fuori rete. La norma prevede un sistema di arbitrato indipendente per dirimere i contrasti sui rimborsi tra assicurazioni e strutture sanitarie."
   ],
