   "sez": "economia",
   "titolo": "La Banca centrale dell'Uzbekistan acquista 7 tonnellate di oro a settembre",
   "orig": "Uzbekistan adds 7 tonnes of gold to reserves in September",
   "lead": "La Banca centrale dell'Uzbekistan ha acquistato sette tonnellate di oro nel mese di settembre, contribuendo al rafforzamento delle proprie riserve auree nazionali. Nello stesso periodo, gli istituti centrali di tutto il mondo hanno incrementato complessivamente le loro riserve auree di sessantuno tonnellate, segnando il livello mensile più elevato dall'inizio dell'anno. La tendenza a detenere metallo prezioso è discussa anche in altri Paesi: in Ghana, l'esponente politico Mahamudu Bawumia ha ribadito ai propri sostenitori l'importanza strategica di conservare le riserve di oro anziché negoziarle sul mercato.",
   "more": [
    "L'oro rappresenta da sempre uno dei principali beni rifugio per le banche centrali, utilizzato per diversificare le riserve valutarie ed evitare l'eccessiva esposizione alle oscillazioni del dollaro o di altre monete. Nei momenti di incertezza geopolitica ed economica, gli acquisti di metallo prezioso da parte degli Stati tendono ad aumentare."
   ],
