   "id": "z09665cbc",
   "sez": "economia",
   "titolo": "Corea del Sud, lo studio legale BKL potenzia il dipartimento antitrust con data analytics",
   "orig": "Bae, Kim & Lee bolsters antitrust practice with 3 new lawyers, expanded data analytics center",
   "lead": "A Seul lo studio legale sudcoreano Bae, Kim & Lee ha rafforzato il proprio dipartimento di antitrust e concorrenza attraverso l'assunzione di tre nuovi avvocati e l'espansione della struttura di analisi economica. La società ha riorganizzato il proprio centro per il diritto e l'economia, istituito nel 2021, trasformandolo nel Center for Economics and Data Analytics. L'unità operativa integrerà competenze di economisti, legali ed esperti di data science per gestire procedimenti complessi legati alla regolamentazione della concorrenza e delle pratiche di mercato. Lo riferisce The Korea Herald.",
   "more": [
    "L'analisi dei dati e la scienza informatica sono diventate essenziali nelle controversie antitrust moderne, in particolare per i mercati digitali e le grandi concentrazioni aziendali. Gli organismi di regolamentazione e gli studi legali utilizzano modelli econometrici avanzati per valutare l'impatto delle posizioni dominanti e delle fusioni societarie sui consumatori."
   ],
