   "id": "za5ce2aab",
   "sez": "cultura",
   "titolo": "Nepal, il film 'Panch Pandav' esce nelle sale tra appelli al boicottaggio e minacce",
   "orig": "‘Panch Pandav’ to hit theatres amid boycott calls and threats",
   "lead": "In Nepal la pellicola cinematografica 'Panch Pandav' approda nei cinema in un clima di forte contestazione, segnato da appelli al boicottaggio e intimidazioni verso gli esercenti. I produttori dell'opera hanno espresso viva preoccupazione dopo le minacce di atti vandalici rivolte a una sala cinematografica nella città di Nepalgunj. Sulla vicenda è intervenuto il ministero delle Comunicazioni nepalese, dichiarando ufficialmente che la proiezione della pellicola deve essere garantita e autorizzata nelle sale senza ostacoli o censure. Lo riferisce The Kathmandu Post.",
   "more": [
    "Le controversie legate all'uscita di opere cinematografiche sono frequenti nell'Asia meridionale quando le trame toccano tematiche religiose, mitologiche o sensibilità comunitarie. In questi contesti, i ministeri dell'informazione e della cultura intervengono spesso per difendere i nulla osta rilasciati dalle commissioni di censura rispetto a proteste di gruppi organizzati."
   ],
