   "sez": "economia",
   "titolo": "Commercio transfrontaliero in Ghana: ostacoli operativi nonostante gli accordi AfCFTA",
   "orig": "GH¢31bn informal cross-border trade faces hurdles despite AfCFTA commitments",
   "lead": "In Ghana il commercio transfrontaliero informale, stimato in 31 miliardi di cedi nei primi tre trimestri del 2025, continua a incontrare pesanti ostacoli operativi sul campo. La situazione suscita dubbi sulla capacità del Paese di trarre pieno beneficio dall'Area di libero scambio continentale africana (AfCFTA). Nel contempo, nella regione dell'Africa occidentale, la Commissione dell'ECOWAS ha promosso iniziative di coordinamento avviando piattaforme nazionali a Conakry per rafforzare la cooperazione sui confini e facilitare la libera circolazione di persone e merci.",
   "more": [
    "L'Area di libero scambio continentale africana (AfCFTA) è un trattato commerciale volto a creare un mercato unico per beni e servizi in Africa, riducendo dazi e barriere doganali. Tuttavia, la persistenza di burocrazia, valute differenti e controlli informali ai valichi ostacola frequentemente l'integrazione economica reale tra i Paesi membri."
   ],
