   "id": "zffcc5bee",
   "sez": "dibattito",
   "titolo": "Germania, dibattito pubblico su integrazione e pregiudizi dopo le proteste della Generazione Z",
   "orig": "Germany’s Gen Z protest riots spark debate on integration and bias",
   "lead": "In Germania i recenti disordini scaturiti dalle proteste della Generazione Z hanno aperto una vivace discussione politica sul rapporto tra integrazione sociale e contrasto ai pregiudizi. Il confronto vede contrapposte le richieste di un'analisi rigorosa delle problematiche di inserimento sociale nei quartieri urbani e il timore che tali argomentazioni possano gettare ombre o sospetti generalizzati su interi gruppi di popolazione o comunità di origine straniera. Le istituzioni e i commentatori si interrogano su come discutere apertamente dei disagi giovanili senza alimentare discriminazioni o etichettature verso le minoranze. Lo riferisce Deutsche Welle.",
   "more": [
    "Il dibattito sull'integrazione e la sicurezza urbana in Germania coinvolge da tempo partiti, sociologi e associazioni civiche. Quando episodi di tensione pubblica vedono protagonisti gruppi di giovani, la discussione politica oscilla regolarmente tra l'esigenza di sicurezza e politiche educative mirate contro l'emarginazione sociale e le discriminazioni strutturali."
   ],
