   "sez": "musica",
   "titolo": "NPR presenta a Tiny Desk Radio le esibizioni di Joan Shelley, Aldana e Ganavya",
   "orig": "Tiny Desk Radio: Joan Shelley, Melissa Aldana with Gonzalo Rubalcaba, Ganavya",
   "lead": "L'emittente statunitense NPR dedica una nuova puntata del programma radiofonico Tiny Desk Radio alle performance di Joan Shelley, Ganavya e della sassofonista Melissa Aldana in coppia con il pianista Gonzalo Rubalcaba. La trasmissione radiofonica, diffusa sulle stazioni locali della rete pubblica americana, propone un percorso sonoro incentrato sui temi della riflessione e del rinnovamento interiore. Lo speciale offre una selezione di arrangiamenti acustici e improvvisazioni jazz ideati per regalare agli ascoltatori un'esperienza musicale meditativa e distensiva. Lo riferisce NPR.",
   "more": [
    "Tiny Desk è un celebre format musicale ideato dalla radio pubblica statunitense NPR, noto in tutto il mondo per concerti intimi registrati dietro una scrivania d'ufficio. Il format privilegia esecuzioni dal vivo essenziali, prive di amplificazioni complesse o effetti elettronici, valorizzando la dimensione acustica dei musicisti."
   ],
