   "id": "zb850a910",
   "sez": "mondo",
   "titolo": "RD Congo, la MONUSCO ribadisce a Beni la priorità della protezione dei civili",
   "orig": "James Swan à Beni : « La protection des civils reste notre priorité »",
   "lead": "A Beni, nella provincia del Nord Kivu, il capo della missione delle Nazioni Unite MONUSCO, James Swan, ha incontrato il governatore provinciale per discutere la situazione securitaria nel territorio del Grande Nord. Al centro dei colloqui istituzionali sono state poste le sfide sanitarie e umanitarie determinate dall'epidemia del virus Ebola, unitamente alla difesa della popolazione locale. Il rappresentante dell'Onu ha dichiarato pubblicamente che la protezione dei civili rimane la priorità assoluta per le forze di pace internazionali operative nella Repubblica Democratica del Congo. Lo riferisce Radio Okapi.",
   "more": [
    "La missione MONUSCO è stata schierata dalle Nazioni Unite per stabilizzare le province orientali della Repubblica Democratica del Congo, martoriate da conflitti armati e gruppi ribelli. La complessità del contesto è aggravata da ricorrenti crisi sanitarie ed epidemie, che mettono a dura prova la tenuta delle strutture di accoglienza."
   ],
