   "sez": "mondo",
   "titolo": "Pakistan, blitz contro un call center a Karachi: 273 arresti per frode internazionale",
   "orig": "Official says 273 arrested in NCCIA raid on 'illegal' call centre on Karachi's Sharea Faisal",
   "lead": "A Karachi la National Cyber Crime Investigation Agency del Pakistan ha arrestato 273 persone durante un blitz condotto contro un call center illegale situato lungo l'arteria Sharea Faisal. Le autorità investigative considerano la struttura la sede operativa di una vasta rete di truffe informatiche su scala internazionale. Nel corso dell'operazione di polizia, illustrata dal direttore aggiunto Shahzad Akbar, sono stati sequestrati 339 computer portatili, 152 telefoni cellulari e 4 postazioni fisse utilizzati per gestire le presunte attività fraudolente. Lo riferisce Dawn.",
   "more": [
    "Il fenomeno dei call center clandestini dediti al phishing e alle truffe telematiche rappresenta una minaccia cibernetica globale. Spesso queste organizzazioni operano da Paesi asiatici fingendosi operatori bancari, tecnici informatici o uffici delle imposte per sottrarre risparmi e dati sensibili a cittadini residenti all'estero."
   ],
