   "id": "z94913263",
   "sez": "cucina",
   "titolo": "A Kathmandu il festival del cibo giapponese tra ricette tipiche e tradizioni",
   "orig": "Beyond sushi and sukiyaki, a taste of Japanese culture in Kathmandu",
   "lead": "Nella capitale nepalese Kathmandu ha preso il via l'annuale festival gastronomico dedicato alla cucina nipponica. L'evento culinario, della durata di una settimana, va oltre la semplice degustazione di piatti tradizionali come sushi e sukiyaki, guidando gli avventori attraverso la cultura e i rituali della tavola giapponese. L'iniziativa introduce i partecipanti alle regole di etichetta, all'estetica della composizione dei piatti e alle tradizioni secolari che caratterizzano la preparazione e il consumo dei pasti in Giappone, favorendo lo scambio culturale attraverso l'esperienza gastronomica. Lo riferisce The Kathmandu Post.",
   "more": [
    "La cucina tradizionale giapponese, nota come washoku, è inserita nel patrimonio culturale immateriale dell'UNESCO. Essa si distingue per la stagionalità degli ingredienti, l'equilibrio dei sapori e il rigoroso rispetto delle regole di etichetta a tavola, aspetti che vengono valorizzati durante le manifestazioni enogastronomiche internazionali."
   ],
