   "id": "z74c67232",
   "sez": "salute",
   "titolo": "Studio su PLOS Medicine: i vaccini contro il Covid-19 hanno generato trilioni di benefici",
   "orig": "COVID-19 vaccines generated trillions in benefits, far exceeding their estimated costs",
   "lead": "Secondo una nuova ricerca scientifica pubblicata sulla rivista PLOS Medicine, i vaccini sviluppati contro il Covid-19 hanno prodotto benefici economici per migliaia di miliardi di dollari, superando di gran lunga le spese sostenute per la loro realizzazione. L'indagine stima che ogni dollaro investito nello sviluppo e nella distribuzione delle dosi abbia generato un ritorno compreso tra 81 e 810 dollari in termini di valore economico generale durante il primo anno di somministrazione, dimostrando l'elevatissima efficacia degli investimenti vaccinali. Lo riferisce Medical Xpress.",
   "more": [
    "Le valutazioni di impatto economico in ambito sanitario calcolano non solo i risparmi sui costi ospedalieri diretti, ma anche la riduzione delle perdite di produttività, la tutela dei posti di lavoro e la ripartenza delle attività commerciali permesse dalla diminuzione delle forme gravi di contagio virale."
   ],
