   "titolo": "Major League Soccer, tutto in palio nel Decision Day del campionato nordamericano",
   "orig": "Wooden Spoon, Golden Boot and playoff spots: what to watch for on MLS Decision Day",
   "lead": "Il massimo campionato di calcio nordamericano si avvia alla conclusione della stagione regolare con il Decision Day, giornata campale in cui si decideranno l'assegnazione dei posti per i playoff, il titolo di capocannoniere e la squadra destinata all'ultimo posto. Il programma prevede una raffica di incontri distribuiti tra la costa orientale e la costa occidentale degli Stati Uniti. Le squadre scendono in campo contemporaneamente per l'ultima opportunità di conquistare un piazzamento utile per la post-season, garantendo un turno conclusivo ricco di verdetti agonistici. Lo riferisce The Guardian.",
   "more": [
    "La Major League Soccer (MLS) segue la struttura tipica dei campionati sportivi professionistici nordamericani, senza retrocessioni e divisa in regular season e playoff finali. Il 'Decision Day' è l'ultima giornata della stagione regolare, disputata simultaneamente per evitare calcoli di classifica prima della fase a eliminazione diretta."
   ],
