   "id": "z9a05e35c",
   "sez": "mondo",
   "titolo": "Intelligenza artificiale e data center, i rischi politici per il governo australiano",
   "orig": "Australians are yet to see the benefits of AI and datacentres – and US midterms show they could be political kryptonite",
   "lead": "Il governo del premier australiano Anthony Albanese dovrebbe muoversi con cautela sul tema dell'intelligenza artificiale e dei data center, scrive The Guardian, osservando che i risultati delle elezioni di metà mandato americane mostrano come il settore possa diventare un argomento politicamente rischioso. Finora, secondo il quotidiano, gli australiani non hanno visto beneficio dal boom dell'IA, ma solo possibili modifiche al diritto d'autore dannose per i creativi locali, nuove regole su energia e acqua, e il timore di perdita di posti di lavoro. Lo riferisce The Guardian.",
   "more": [
    "L'espansione dei data center per l'intelligenza artificiale richiede grandi quantità di energia e acqua, generando tensioni locali in diversi paesi. I governi si trovano a dover bilanciare gli investimenti tecnologici con le preoccupazioni di cittadini e lavoratori, un tema emerso anche nelle recenti elezioni statunitensi."
   ],
