   "id": "zcb0f213e",
   "sez": "mondo",
   "titolo": "La Corte Ue: i cibi al CBD devono avere l'autorizzazione alla vendita per essere certificati biologici",
   "orig": "EU court says CBD foods need approval for sale before they can be certified organic",
   "lead": "La Corte di giustizia dell'Unione europea ha stabilito che gli alimenti contenenti CBD, il composto derivato dalla cannabis, non possono ottenere la certificazione biologica senza aver prima ricevuto l'autorizzazione alla vendita. La sentenza riguarda l'uso del cannabidiolo nei prodotti alimentari, che richiede un'autorizzazione specifica anche prima di poter procedere alla certificazione come prodotto biologico. Lo riferisce Deutsche Welle.",
   "more": [
    "Il CBD è un composto non psicoattivo estratto dalla pianta di cannabis, il cui utilizzo negli alimenti è regolato a livello europeo da norme sulla sicurezza alimentare. Le aziende che vogliono commercializzare prodotti a base di CBD devono affrontare un iter di autorizzazione separato da quello necessario per la certificazione biologica."
   ],
