   "id": "zdff54e34",
   "sez": "prima",
   "titolo": "Dopo l'onda blu democratica, dubbi su un rapido calo dei prezzi di benzina e gasolio",
   "orig": "Does the blue wave mean lower gasoline and diesel prices soon? Don't hold your breath",
   "lead": "Dopo la vittoria democratica alle elezioni di metà mandato, una nuova maggioranza al Congresso potrebbe fare pressione sul presidente per porre fine alla guerra in Iran, ma secondo NPR sarà più difficile per i democratici incidere direttamente sui prezzi dei carburanti, legati a un complesso mercato petrolifero internazionale. Altre testate analizzano le conseguenze del voto su sport, rapporti Usa-India, Iran, Cina e Caucaso, osservando come il nuovo equilibro di potere a Washington possa influenzare diversi dossier internazionali nei prossimi mesi.",
   "more": [
    "Le elezioni di metà mandato negli Stati Uniti rinnovano parte del Congresso e possono modificare gli equilibri di potere rispetto alla Casa Bianca. Una vittoria democratica, come quella di questa settimana, rafforza la capacità del Congresso di fare pressione sull'amministrazione su temi come la politica estera, pur senza poteri diretti su variabili di mercato come i prezzi energetici."
   ],
