   "id": "z57a798a8",
   "sez": "adolescenti",
   "titolo": "È uscito il remake di Zelda: Ocarina of Time, già elogiato dalla critica",
   "orig": "It's Z day - remake of iconic Legend of Zelda game is released",
   "lead": "È stato pubblicato il remake del celebre videogioco The Legend of Zelda: Ocarina of Time, uscito originariamente nel 1998, con recensioni entusiastiche fin dal debutto. Secondo The Guardian, la nuova versione per Nintendo Switch 2 rende il gioco più chiaro e semplice da navigare, più bello visivamente e con tocchi musicali aggiuntivi, mantenendo però la malinconia dell'originale. la Repubblica definisce il remake una piccola gemma capace di far scoprire e riscoprire un capolavoro senza tempo della storia dei videogiochi.",
   "more": [
    "The Legend of Zelda: Ocarina of Time, uscito nel 1998 per Nintendo 64, è considerato uno dei videogiochi più influenti della storia per l'introduzione di meccaniche di gioco in 3D poi diventate standard del genere action-adventure. I remake di classici del genere permettono alle nuove generazioni di giocatori di scoprire titoli storici con grafica e controlli aggiornati."
   ],
