   "titolo": "Qatar Airways amplia la rete con nuovi collegamenti da Doha a Caracas e Bogotà",
   "orig": "Qatar Airways Expands Global Network with New Doha Connections to Caracas and Bogotá",
   "lead": "Qatar Airways ha annunciato l'apertura di nuovi collegamenti da Doha verso Caracas e Bogotà, che diventano rispettivamente la sedicesima e la diciassettesima destinazione servite dalla compagnia nel continente americano. Si tratta dei primi collegamenti diretti di una compagnia del Golfo verso Venezuela e Colombia, un'espansione che amplia ulteriormente la rete della compagnia qatariota nelle Americhe.",
   "more": [
    "Le compagnie aeree del Golfo hanno negli ultimi anni ampliato progressivamente le proprie rotte verso l'America Latina, puntando sul ruolo di hub intercontinentale di aeroporti come quello di Doha per collegare l'area con Asia, Africa e Medio Oriente senza scali intermedi."
   ],
