   "sez": "prima",
   "titolo": "Ucraina, Meloni a Costa: inaccettabile che l'Ue proceda in ordine sparso",
   "orig": "Ucraina, Meloni: Ue abbia una sola voce",
   "lead": "La premier Giorgia Meloni ha scritto al presidente del Consiglio europeo Antonio Costa chiedendo che l'Unione europea parli con una sola voce sulla guerra in Ucraina, definendo inaccettabile che l'Europa continui a procedere in ordine sparso. Secondo Il Sole 24 Ore, Meloni avrebbe affermato che così si favorisce solo chi vuole che la guerra continui, chiedendo che entro dicembre sia formalizzata la scelta di un negoziatore unico. Sky TG24 segnala che Melania Trump terrà lo stesso giorno un evento alla Casa Bianca sugli sforzi per un cessate il fuoco tra Russia e Ucraina.",
   "more": [
    "La mancanza di una posizione unica dell'Unione europea sulla guerra in Ucraina riflette le divergenze tra i governi dei paesi membri su strategia negoziale e livello di coinvolgimento militare. La richiesta italiana di un negoziatore unico si inserisce in un più ampio dibattito europeo su come rafforzare il peso dell'Ue nei negoziati con Russia e Stati Uniti."
   ],
