   "id": "zd6df0b5e",
   "sez": "spazio",
   "titolo": "Le luci delle città del Midwest americano fotografate dalla Stazione spaziale",
   "orig": "Midwestern City Lights",
   "lead": "La Nasa ha pubblicato una fotografia che mostra le luci delle città del Midwest degli Stati Uniti fino alla costa orientale, scattata un paio d'ore prima dell'alba del 18 ottobre 2026. Tra le aree urbane visibili nell'immagine figurano Chicago, Detroit e l'area metropolitana di New York. La fotografia è stata scattata dalla Stazione spaziale internazionale, che orbitava a 259 miglia sopra la Terra al momento dello scatto. Lo riferisce Nasa.",
   "more": [
    "La Stazione spaziale internazionale orbita a circa 400 chilometri di altitudine e viene spesso utilizzata per scattare fotografie notturne della Terra, utili sia per scopi scientifici che divulgativi, mostrando la distribuzione delle aree urbane e l'intensità dell'illuminazione artificiale nelle diverse regioni del pianeta."
   ],
