   "id": "ze54fabfb",
   "sez": "sport",
   "titolo": "Harry Kane rinnova con il Bayern Monaco fino al 2029",
   "orig": "Ballon d’Or winner Harry Kane signs new contract with Bayern through to 2029",
   "lead": "Harry Kane, attaccante inglese e vincitore del Pallone d'Oro, ha rinnovato il contratto con il Bayern Monaco fino al 2029. Il giocatore, arrivato dal Tottenham nel 2023 per una cifra record di 100 milioni di euro, ha segnato 156 gol in 161 presenze con i bavaresi, contribuendo a due titoli di Bundesliga e una Coppa di Germania. Kane ha dichiarato di amare il club, i tifosi e la città di Monaco.",
   "more": [
    "Harry Kane è il capitano della nazionale inglese e nel 2026 ha vinto il Pallone d'Oro, il premio individuale più prestigioso nel calcio mondiale. Il suo trasferimento al Bayern Monaco nel 2023 fu uno dei più costosi della storia del club tedesco, e da allora il giocatore è diventato uno dei protagonisti del campionato tedesco."
   ],
