   "sez": "economia",
   "titolo": "Maxi frode sugli alcolici a Rimini, sequestrati oltre 7 milioni di euro",
   "orig": "Maxi frode su alcolici a Rimini, sequestrati oltre 7 milioni di euro: coinvolte anche due società sammarinesi",
   "lead": "Un'indagine dell'Agenzia delle Dogane e dei Monopoli, condotta con la Guardia di Finanza, ha portato al sequestro di oltre 7 milioni di euro nell'ambito di una maxi frode sugli alcolici a Rimini. Il sistema scoperto si basava su vendite fittizie e crediti fiscali inesistenti, con una rete estesa a diversi paesi europei. Nell'inchiesta risultano coinvolte anche due società con sede a San Marino. Lo riferisce San Marino RTV.",
   "more": [
    "Le frodi fiscali legate alla vendita di alcolici e ad altri beni soggetti ad accisa sfruttano spesso catene di società fittizie per generare crediti d'imposta non dovuti, riducendo il gettito fiscale e falsando la concorrenza. Le indagini di questo tipo coinvolgono tipicamente più autorità doganali e finanziarie a livello internazionale."
   ],
