   "sez": "mondo",
   "titolo": "Stati Uniti, cade il caso penale contro la scienziata russa accusata di aver trasportato embrioni di rana",
   "orig": "US court drops criminal case against Russian scientist Kseniia Petrova, accused of smuggling frog embryos",
   "lead": "Un giudice federale negli Stati Uniti ha fatto cadere tutte le accuse penali contro la scienziata russa Kseniia Petrova, arrestata e trattenuta per quattro mesi dopo essere stata fermata con campioni di ricerca, tra cui embrioni di rana. Petrova lavorava alla Harvard Medical School e temeva di essere deportata in Russia. I procuratori federali hanno deciso di ritirare il caso dopo la lunga detenzione.",
   "more": [
    "Negli ultimi anni i controlli alla frontiera statunitense su ricercatori stranieri e materiali scientifici sono aumentati, generando casi controversi legati a normative doganali su campioni biologici. Il caso di Petrova aveva attirato attenzione per il rischio di deportazione verso la Russia, paese da cui la scienziata era fuggita."
   ],
