   "titolo": "Turchia, piano da 100 miliardi di dollari per eolico e solare entro il 2040",
   "orig": "Turkey sets $100 bln wind and solar expansion target for 2040",
   "lead": "Il ministro dell'Energia turco Alparslan Bayraktar ha presentato giovedì a Istanbul un piano per quasi quadruplicare la capacità eolica e solare della Turchia entro il 2040, con investimenti stimati in circa 100 miliardi di dollari. L'obiettivo della strategia \"National Energy 2040\" è ridurre la dipendenza dai combustibili importati e far fronte alla crescente domanda elettrica del paese. Lo riferisce l'agenzia statale Anadolu.",
   "more": [
    "La Turchia importa gran parte dell'energia fossile che consuma, con un impatto significativo sulla bilancia commerciale nazionale. Investire in fonti rinnovabili come eolico e solare consente di ridurre tale dipendenza e di rispondere alla crescente domanda di elettricità legata a popolazione e industrializzazione."
   ],
