   "titolo": "Mattarella: chi nasce al Sud deve poter restare o tornare",
   "orig": "Mattarella: \"Chi nasce al Sud possa restare o tornare, è interesse nazionale\"",
   "lead": "Il presidente della Repubblica Sergio Mattarella, intervenendo al ventennale della Fondazione Con il Sud, ha affermato che chi nasce nel Mezzogiorno deve poter scegliere di restare o di tornarvi, definendolo un interesse nazionale. Il capo dello Stato ha sottolineato l'importanza di invertire la tendenza allo spopolamento delle regioni meridionali. Lo riferisce ANSA.",
   "more": [
    "Il tema dello spopolamento del Sud Italia, legato alla migrazione di giovani verso il Nord o l'estero in cerca di lavoro, è oggetto da anni di politiche di sviluppo territoriale e di coesione sociale, tra cui l'attività di fondazioni come Con il Sud, nate per sostenere progetti di comunità nelle regioni meridionali."
   ],
