   "titolo": "Dov'è finito il cinema erotico italiano",
   "orig": "Dov’è finito il cinema erotico",
   "lead": "Il cinema erotico italiano, che tra gli anni Settanta e Novanta ebbe un ruolo rilevante anche grazie a Tinto Brass, ha progressivamente perso centralità nel panorama cinematografico nazionale. Il Post analizza le ragioni del declino di un genere che per decenni ha avuto un pubblico consistente nelle sale italiane.",
   "more": [
    "Il cinema erotico italiano nacque negli anni Settanta sulla scia della liberalizzazione dei costumi, trovando in autori come Tinto Brass un punto di riferimento. Con la diffusione di video, internet e contenuti pornografici accessibili online, il genere ha progressivamente perso il pubblico delle sale cinematografiche."
   ],
