   "sez": "italia",
   "titolo": "Il voto dei giovani e le risposte di Meloni, secondo Repubblica",
   "orig": "L’effetto giovani sul voto e le risposte di Meloni. Ecco perché per i ventenni ci sono solo briciole",
   "lead": "Secondo un'analisi di Repubblica, gli elettori tra i 18 e i 34 anni hanno trainato l'affluenza al referendum sulla separazione delle carriere, votando in maggioranza per il No. Lo stesso dato demografico, secondo l'articolo, avrebbe contribuito anche all'ondata elettorale che ha coinvolto Donald Trump. Il quotidiano si interroga sulle risposte che la premier Giorgia Meloni può offrire a una generazione che percepisce poche opportunità concrete.",
   "more": [
    "Nei referendum e nelle elezioni recenti, in Italia come altrove, la partecipazione dei giovani elettori è spesso indicata come fattore chiave negli esiti elettorali, specialmente quando le proposte in discussione riguardano riforme istituzionali o temi percepiti come divisivi tra generazioni."
   ],
