   "sez": "ingegneria",
   "titolo": "I paesaggi urbani ecologici di Kongjian Yu",
   "orig": "making room for nature: the urban landscapes of kongjian yu",
   "lead": "Un approfondimento di Designboom illustra i progetti urbani dell'architetto paesaggista cinese Kongjian Yu e del suo studio Turenscape, dedicati a integrare zone umide, corsi d'acqua e habitat ripristinati nelle infrastrutture urbane. L'obiettivo di questi interventi è creare spazi condivisi tra persone e altre forme di vita all'interno delle città.",
   "more": [
    "Turenscape è noto a livello internazionale per l'approccio della \"città spugna\", che utilizza paesaggi naturali come zone umide e parchi per gestire le acque piovane e ridurre il rischio di alluvioni, integrando ecologia e pianificazione urbana in numerose città."
   ],
