   "id": "z859efe31",
   "sez": "mondo",
   "titolo": "Premiato lo scienziato che denunciò la contaminazione da piombo a Flint",
   "orig": "Scientist who exposed lead contamination in drinking water wins award for standing up for science",
   "lead": "Siddhartha Roy, scienziato ambientale della Rutgers University, ha vinto il premio Maddox per aver difeso la scienza dopo aver guidato il team che individuò la contaminazione da piombo nell'acqua potabile di Flint, nel Michigan, nel 2015. Le sue scoperte contraddissero le rassicurazioni delle autorità statali e federali, provocando uno scandalo nazionale e una causa collettiva risolta con un risarcimento multimilionario. Lo riferisce The BMJ.",
   "more": [
    "La crisi dell'acqua di Flint, scoppiata nel 2014-2015, nacque dal cambio della fonte di approvvigionamento idrico della città, che causò la corrosione delle tubature e il rilascio di piombo nell'acqua potabile, con gravi conseguenze sanitarie per migliaia di residenti, in particolare bambini."
   ],
