   "id": "zc98464ff",
   "sez": "adolescenti",
   "titolo": "Immissioni in ruolo ATA 2026/27, coperto il 99% del contingente",
   "orig": "Immissioni in ruolo ATA 2026/27, coperto il 99% del contingente. Dal Pino (Anief): “Ancora 1.025 candidati nelle graduatorie DSGA”",
   "lead": "Nelle immissioni in ruolo del personale ATA per l'anno scolastico 2026/27 è stato coperto il 99% del contingente previsto, secondo i dati illustrati da Cristina Dal Pino dell'Anief durante un Question Time di Orizzonte Scuola. Restano scoperti 1.025 candidati nelle graduatorie per il ruolo di DSGA. I dati derivano dal tavolo tecnico del ministero dell'Istruzione del 27 ottobre 2026. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il personale ATA (amministrativo, tecnico e ausiliario) è una componente essenziale del funzionamento delle scuole italiane, e le immissioni in ruolo annuali vengono monitorate dai sindacati per verificare la copertura effettiva dei posti disponibili, specialmente per figure chiave come i direttori dei servizi generali e amministrativi (DSGA)."
   ],
