   "titolo": "Roma, dopo il caso Milano gli architetti chiedono un nuovo Testo unico dell'edilizia",
   "orig": "Roma, rigenerazione urbana dopo il caso Milano: gli architetti chiedono un nuovo Testo unico dell'edilizia",
   "lead": "Dopo il caso urbanistico di Milano, gli architetti romani chiedono un nuovo Testo unico dell'edilizia per chiarire le norme sulla rigenerazione urbana. La richiesta nasce dal caso milanese in cui una Scia alternativa al permesso di costruire avrebbe permesso di avviare una ristrutturazione con demolizione e ricostruzione senza le dovute autorizzazioni. Lo riferisce Il Messaggero.",
   "more": [
    "La Scia (Segnalazione certificata di inizio attività) è una procedura semplificata che consente di avviare lavori edilizi senza attendere un permesso di costruire esplicito, ma il suo utilizzo per interventi di demolizione e ricostruzione ha generato controversie legali in diverse città italiane, alimentando il dibattito sulla necessità di una normativa edilizia nazionale più chiara."
   ],
