   "sez": "economia",
   "titolo": "Cuba, l'economia procede 'a due velocità': le imprese statali arretrano, quelle private crescono",
   "orig": "La economía cubana opera “a dos velocidades”: las empresas estatales se hunden y las privadas crecen",
   "lead": "Un organismo economico cubano segnala che l'economia dell'isola si muove 'a due velocità': le imprese statali sono in difficoltà mentre quelle private continuano a crescere. Secondo l'analisi, il dinamismo del settore privato resta però insufficiente per ricostituire la capacità produttiva complessiva del Paese, perché le sue attività si concentrano soprattutto nel commercio e non nella produzione. Lo riferisce 14ymedio.",
   "more": [
    "Da anni Cuba convive con una crisi economica segnata da carenza di valuta, blackout energetici e calo della produzione industriale. Negli ultimi anni il governo ha permesso l'espansione di piccole e medie imprese private, soprattutto nel commercio e nei servizi, mentre le aziende statali, che dominano i settori strategici, mostrano segni di stagnazione."
   ],
