   "id": "z229f1753",
   "sez": "mondo",
   "titolo": "Myanmar, la Cina allenta le restrizioni commerciali in alcuni valichi di frontiera negli Stati Kachin e Shan",
   "orig": "China eases trade restrictions at select border gates in Kachin and Shan states",
   "lead": "La Cina ha allentato alla fine del mese scorso le restrizioni al commercio in alcuni valichi di frontiera con gli Stati Kachin e Shan, in Myanmar, escludendo però l'unico valico controllato dal gruppo armato TNLA e due valichi considerati critici controllati dal KIA. Lo riferisce Myanmar Now.",
   "more": [
    "Gli Stati Kachin e Shan, al confine tra Myanmar e Cina, sono teatro di conflitti tra l'esercito birmano e diversi gruppi armati etnici, tra cui il TNLA e il KIA. Pechino usa spesso la gestione dei valichi commerciali come leva politica verso i gruppi armati e il governo militare birmano."
   ],
