   "id": "z5cc11c7f",
   "sez": "mondo",
   "titolo": "Thailandia, la Cina chiede l'arresto di cinque uiguri detenuti a Bangkok",
   "orig": "China seeks arrest of five Uyghurs held in Thailand: Bangkok",
   "lead": "Cinque uiguri detenuti in Thailandia dal 2014 sono oggetto di mandati di arresto emessi dalla Cina, ha dichiarato il capo della sicurezza thailandese. Un tribunale dovrà decidere se saranno rimpatriati in Cina. Gruppi per i diritti umani hanno espresso preoccupazione per la sorte dei cinque uomini, membri della minoranza musulmana uigura che secondo gli attivisti è perseguitata in Cina. Lo riferisce Hong Kong Free Press.",
   "more": [
    "Gli uiguri sono una minoranza musulmana turcofona concentrata nella regione cinese dello Xinjiang, dove organizzazioni per i diritti umani denunciano da anni repressione, detenzioni di massa e controllo sistematico da parte delle autorità cinesi. Pechino nega le accuse, parlando di misure antiterrorismo."
   ],
