   "id": "z0545fcf3",
   "sez": "dibattito",
   "titolo": "Regno Unito, una commissione parlamentare denuncia la dipendenza 'pericolosa' dalla Cina per i minerali critici",
   "orig": "UK found to be ‘dangerously’ reliant on China for critical minerals needed for defence and AI",
   "lead": "Una commissione parlamentare britannica ha concluso che il Regno Unito dipende in modo 'pericoloso' dalla Cina per i materiali critici necessari alla difesa, alle infrastrutture per le energie rinnovabili e all'intelligenza artificiale. I deputati della commissione per il commercio chiedono una politica centralizzata e la creazione di un fondo dedicato al finanziamento di miniere di terre rare e di altri minerali critici, per diversificare le fonti di approvvigionamento. Secondo i parlamentari, anche l'obiettivo di azzerare le emissioni nette rischia di essere compromesso da questa dipendenza. Lo riferisce il Guardian.",
   "more": [
    "I minerali critici, tra cui le terre rare, sono componenti essenziali per batterie, turbine eoliche, semiconduttori e sistemi di difesa. La Cina controlla gran parte dell'estrazione e, soprattutto, della raffinazione mondiale di questi materiali, una posizione che preoccupa i governi occidentali impegnati nella transizione energetica e nello sviluppo tecnologico."
   ],
