   "id": "ze9abd860",
   "sez": "mondo",
   "titolo": "Germania, nessun segno di responsabilità altrui nella morte del ministro bavarese Aiwanger",
   "orig": "Aiwanger starb laut ersten Erkenntnissen ohne Fremdverschulden",
   "lead": "Un giorno dopo la morte improvvisa del leader dei Liberi Elettori Hubert Aiwanger, i primi risultati delle indagini non indicano responsabilità altrui. La sua scomparsa ha scosso la politica bavarese: sugli edifici statali è stato disposto il lutto e a Monaco è stato allestito un libro di condoglianze. Il partito dei Liberi Elettori deve ora riorganizzarsi senza la sua figura più rappresentativa. Lo riferiscono Tagesschau, Der Spiegel e Süddeutsche Zeitung.",
   "more": [
    "Hubert Aiwanger ha guidato i Liberi Elettori portandoli nel governo regionale bavarese insieme alla CSU, diventando una delle figure politiche più note della Baviera per il suo stile diretto. Ulteriori accertamenti medico-legali sono previsti nell'ambito dell'inchiesta aperta sulle cause della morte."
   ],
