   "titolo": "Il Bid approva per la Bolivia crediti per 750 milioni di dollari destinati a stabilizzazione e riforme fiscali",
   "orig": "BID aprueba créditos para Bolivia por $us 750 millones para estabilización y reformas fiscales",
   "lead": "La Banca Interamericana di Sviluppo (BID) ha approvato due prestiti per la Bolivia per un totale di 750 milioni di dollari: 500 milioni come supporto di bilancio per contribuire alla stabilizzazione economica e 250 milioni per sostenere riforme fiscali. L'approvazione arriva dopo l'accordo della Bolivia con il Fondo monetario internazionale e nel mezzo degli sforzi del governo per stabilizzare l'economia. Lo riferiscono Brújula Digital ed El Deber.",
   "more": [
    "La Banca Interamericana di Sviluppo è un'istituzione finanziaria che concede prestiti ai Paesi dell'America Latina e dei Caraibi per progetti di sviluppo economico e sociale. La Bolivia affronta da tempo difficoltà nella bilancia dei pagamenti e nelle riserve valutarie, che hanno portato il governo a cercare sostegno finanziario internazionale."
   ],
