   "lead": "Il terzo processo in corso contro il miliardario austriaco René Benko a Innsbruck affronta gravi accuse di frodi su larga scala perpetrate ai danni di diversi co-investitori interessati. Precedenti condanne lo riguardavano esclusivamente per reati minori. Lo riferisce Süddeutsche Zeitung.",
