   "id": "zce70fd6d",
   "sez": "prima",
   "titolo": "Un cuoco italiano licenziato per aver rifiutato di mettere l'ananas sulla pizza",
   "orig": "Was an Italian chef really fired over refusal to put pineapple on pizza?",
   "lead": "La BBC racconta la vicenda di Davide Tamburella, cuoco italiano licenziato da un ristorante australiano dopo aver rifiutato di utilizzare l'ananas come condimento per la pizza, definendolo un'offesa alla propria cultura. Tamburella si è rivolto alla Fair Work Commission australiana per chiedere di essere reintegrato nel suo posto di lavoro, ma la richiesta è stata respinta dall'organismo. Il caso ha riacceso il dibattito sulla controversa pratica di mettere l'ananas sulla pizza hawaiana, piatto molto diffuso in Australia ma spesso criticato dai puristi della cucina italiana. Lo riferisce BBC News.",
   "more": [
    "La pizza hawaiana, con ananas e prosciutto, è nata in Canada negli anni Sessanta e si è diffusa soprattutto nei paesi anglosassoni, diventando oggetto di dibattiti ricorrenti sulla sua compatibilità con la tradizione culinaria italiana, che generalmente non prevede frutta tra gli ingredienti della pizza."
   ],
