   "id": "zff62bdc6",
   "sez": "mondo",
   "titolo": "La Corea del Nord invita l'Unione Europea a non occuparsi dei suoi affari interni",
   "orig": "North Korea tells EU to 'mind its own business' on human rights",
   "lead": "La missione nordcoreana alle Nazioni Unite ha criticato duramente l'Unione Europea dopo una bozza di risoluzione dell'ONU sui diritti umani riguardante Pyongyang. Secondo Deutsche Welle, la Corea del Nord ha affermato che l'Occidente non ha il monopolio sui diritti umani, invitando l'UE a occuparsi delle proprie questioni interne. La vicenda si inserisce nel confronto ricorrente tra Pyongyang e le istituzioni internazionali sul tema dei diritti umani nel paese. Lo riferisce Deutsche Welle.",
   "more": [
    "Le Nazioni Unite presentano periodicamente risoluzioni sui diritti umani in Corea del Nord, basate su rapporti che denunciano repressione, lavori forzati e limitazioni alle libertà fondamentali. Pyongyang respinge sistematicamente tali accuse, definendole ingerenze politiche occidentali."
   ],
