   "id": "z5abb167f",
   "sez": "cultura",
   "titolo": "Il Brasile ospita per la prima volta il festival AI Film Awards",
   "orig": "Festival discute uso de inteligência artificial na montagem de filmes",
   "lead": "Il Brasile ospiterà per la prima volta il festival AI Film Awards Brasil, in programma dal 6 all'8 novembre, dedicato all'uso dell'intelligenza artificiale nella realizzazione di film. Secondo Agência Brasil, la rassegna presenterà 70 film selezionati, realizzati in vario grado con strumenti di intelligenza artificiale, tra cui il brasiliano 'Submersivos', che apre la mostra. Parteciperanno anche produzioni provenienti da Spagna, Stati Uniti, Cina e Corea del Sud, offrendo un confronto internazionale sulle nuove tecniche di produzione cinematografica.",
   "more": [
    "L'intelligenza artificiale generativa viene sempre più utilizzata nel cinema per creare effetti visivi, montaggi e persino intere scene, suscitando un dibattito internazionale su etica, diritti d'autore e impatto sul lavoro di registi e tecnici del settore audiovisivo."
   ],
