   "id": "z7ee93488",
   "sez": "salute",
   "titolo": "Gli operatori sanitari in sciopero a Mbandaka aderiranno alla campagna contro il colera",
   "orig": "Les agents de santé grévistes acceptent de participer à la campagne de vaccination contre le choléra à Mbandaka",
   "lead": "Gli infermieri e gli operatori sanitari in sciopero a Mbandaka, nella Repubblica Democratica del Congo, hanno deciso di partecipare alla campagna di vaccinazione contro il colera prevista dal 6 al 15 novembre, nonostante lo sciopero che paralizza il settore sanitario nella provincia dell'Équateur. Secondo Radio Okapi, la decisione è stata presa martedì 2 novembre dagli operatori, pur mantenendo lo stato di agitazione per le proprie rivendicazioni. La vicenda mostra la volontà di garantire la risposta sanitaria d'emergenza pur continuando la protesta sindacale in corso. Lo riferisce Radio Okapi.",
   "more": [
    "Il colera è una malattia infettiva intestinale diffusa in aree con scarso accesso ad acqua potabile e servizi igienici adeguati. La Repubblica Democratica del Congo registra periodicamente focolai dell'epidemia, con campagne di vaccinazione organizzate dalle autorità sanitarie per contenerne la diffusione."
   ],
