   "sez": "ingegneria",
   "titolo": "Lo studio shedkm trasforma una caserma storica in chiesa a Manchester",
   "orig": "RetroFirst stories: shedkm transforms listed army barracks into a church",
   "lead": "Lo studio di architettura shedkm ha progettato la trasformazione di una caserma militare vincolata di grado II in nuovi spazi per una chiesa a Manchester. Secondo The Architects' Journal, l'architetto Darren Jones ha illustrato il progetto di recupero e riqualificazione dell'edificio storico. L'intervento si inserisce nella serie 'RetroFirst' dedicata ai progetti di riuso di edifici esistenti nel Regno Unito. La vicenda evidenzia come strutture militari storiche possano essere riconvertite per nuovi usi comunitari. Lo riferisce The Architects' Journal.",
   "more": [
    "RetroFirst è un'iniziativa promossa da architetti e associazioni di settore nel Regno Unito per promuovere il riuso e la ristrutturazione di edifici esistenti al posto della demolizione e nuova costruzione, con l'obiettivo di ridurre l'impatto ambientale del settore edilizio."
   ],
