   "id": "z8ed3e849",
   "sez": "organizzazioni",
   "titolo": "L'ONU avverte: i fondi per l'adattamento climatico restano insufficienti",
   "orig": "‘The world is not ready’: Climate adaptation cash falls far short as warming heads past 1.5°C",
   "lead": "Un rapporto del Programma delle Nazioni Unite per l'Ambiente (UNEP), pubblicato mercoledì, avverte che i finanziamenti destinati ad aiutare le comunità ad adattarsi al cambiamento climatico restano molto inferiori alle necessità, nonostante il riscaldamento globale sia destinato a superare 1,5°C. Secondo UN News, il mondo non è pronto ad affrontare gli effetti del cambiamento climatico con le risorse attualmente disponibili. Il rapporto sollecita un aumento significativo degli investimenti per l'adattamento nei paesi più vulnerabili. Lo riferisce UN News.",
   "more": [
    "L'adattamento climatico comprende le misure che permettono a comunità e territori di ridurre i danni causati da eventi climatici estremi, come dighe, sistemi di irrigazione o infrastrutture resistenti. I paesi in via di sviluppo richiedono da anni maggiori finanziamenti internazionali per queste misure, spesso senza riceverli nella misura necessaria."
   ],
