   "id": "z4fd841d1",
   "sez": "adolescenti",
   "titolo": "Un deputato britannico critica il tempo trascorso dai bambini sul gioco educativo TT Rockstar",
   "orig": "Children spending too long on educational game, MP says",
   "lead": "Un parlamentare britannico ha dichiarato che i giochi educativi come TT Rockstar sono dannosi per i bambini a causa del tempo eccessivo che vi dedicano. Secondo BBC Newsround, il creatore del gioco ha risposto affermando di collaborare con le scuole per limitare il tempo trascorso davanti allo schermo dagli studenti. La discussione riguarda l'equilibrio tra l'uso didattico degli strumenti digitali nelle scuole e i rischi legati a un utilizzo eccessivo degli schermi da parte dei più giovani. Lo riferisce BBC Newsround.",
   "more": [
    "I giochi educativi digitali, usati spesso nelle scuole per l'apprendimento della matematica o di altre materie, sollevano periodicamente dibattiti sul tempo che i bambini trascorrono davanti agli schermi, con pediatri ed esperti che raccomandano limiti giornalieri per l'uso dei dispositivi digitali tra i più giovani."
   ],
