   "titolo": "Il film indiano più costoso di sempre divide la critica",
   "orig": "India's costliest film retells a beloved Hindu epic - but divides critics",
   "lead": "'Ramayana: Rise of a Legend', il film bollywoodiano più atteso dell'anno e il più costoso mai prodotto in India, racconta la prima parte dell'epopea induista del Ramayana, incentrata su Rama, avatar del dio Vishnu. La pellicola, diretta da Nitesh Tiwari, ha diviso i critici nonostante l'attesa enorme attorno all'uscita. Lo riferisce BBC News.",
   "more": [
    "Il Ramayana è uno dei testi epici fondamentali dell'induismo, narrando le vicende del principe Rama. Bollywood produce regolarmente adattamenti di testi religiosi e mitologici indiani, che godono di grande attenzione popolare e spesso generano dibattiti tra critica e pubblico sulla fedeltà alla tradizione."
   ],
