   "id": "z46af1c03",
   "sez": "ingegneria",
   "titolo": "Incendio e fuoriuscita di petrolio in una sottostazione elettrica ad Auckland",
   "orig": "Oil spill after major fire at Auckland power substation",
   "lead": "Un incendio ha colpito giovedì una sottostazione elettrica della società Vector a Penrose, quartiere di Auckland, in Nuova Zelanda, durante lavori di manutenzione. Tre dipendenti dell'azienda sono rimasti feriti e sono stati ricoverati in ospedale. L'incendio ha provocato anche una fuoriuscita di petrolio nell'impianto. Dense colonne di fumo si sono alzate sopra la zona, visibili da gran parte della città, prima che le fiamme venissero spente dai soccorritori.",
   "more": [
    "Le sottostazioni elettriche trasformano l'energia ad alta tensione in corrente utilizzabile dalla rete di distribuzione urbana; un incendio in questi impianti può causare interruzioni di corrente estese e comporta rischi per chi vi lavora, data la presenza di trasformatori con oli isolanti infiammabili."
   ],
