   "sez": "mondo",
   "titolo": "Il PS andorrano chiede conto della cessione di dati dei dipendenti pubblici a un'azienda privata",
   "orig": "El PS demana explicacions pel traspàs de dades dels funcionaris a una empresa privada",
   "lead": "La consigliera del Partito Socialdemocratico Laia Moliné ha chiesto al governo di Andorra la Vella spiegazioni sul trasferimento dei dati dei funzionari pubblici a un'azienda privata. Moliné si interroga anche sulla necessità di fornire il numero identificativo (NIA) dei lavoratori all'impresa esterna. La consigliera ha inoltre domandato come verrà applicato il nuovo sistema di valutazione delle prestazioni dei dipendenti pubblici, annunciato dall'esecutivo. La questione è stata posta in sede parlamentare come interrogazione al governo andorrano.",
