   "id": "z4ae7737e",
   "sez": "mondo",
   "titolo": "La Turchia ferma 34 donne russe in retate in locali notturni ad Ankara",
   "orig": "Turkish authorities detain 34 Russian women in nightclub raids over alleged ‘morality and public safety violations’",
   "lead": "Le autorità turche hanno fermato 34 donne di nazionalità russa durante controlli in alcuni locali notturni di Ankara, secondo quanto riferito dall'ambasciata russa in Turchia. I fermi sarebbero avvenuti a fine ottobre nel quadro di controlli su presunte violazioni legate a \"moralità e sicurezza pubblica\". L'ambasciata ha dichiarato di essere ancora in attesa di informazioni dalle autorità turche sulle motivazioni precise dei fermi. Non sono stati forniti ulteriori dettagli sulle accuse specifiche o sulla situazione attuale delle donne coinvolte.",
   "more": [
    "Le autorità turche effettuano periodicamente controlli nei locali notturni delle principali città, spesso collegati a indagini su presunta prostituzione o immigrazione irregolare. Tali operazioni hanno in diverse occasioni coinvolto cittadine straniere, in particolare provenienti da paesi dell'ex Unione Sovietica."
   ],
