   "sez": "economia",
   "titolo": "L'Uzbekistan raccoglie oltre 5 milioni di tonnellate di cotone, record dall'indipendenza",
   "orig": "Uzbekistan Cotton Harvest Exceeds 5 Million Tons for First Time Since Independence",
   "lead": "L'Uzbekistan ha raccolto nel 2026 più di 5 milioni di tonnellate di cotone grezzo, il risultato più alto registrato dal paese dalla sua indipendenza nel 1991. Il presidente Shavkat Mirziyoyev ha definito il dato un record storico in un messaggio di congratulazioni ai lavoratori agricoli, sottolineando che la produttività media ha raggiunto circa 70 centinaia per ettaro. Il risultato rafforza la base di materie prime per l'industria tessile nazionale, cresciuta negli ultimi decenni dopo anni di cali produttivi.",
   "more": [
    "Il cotone è stato per decenni la coltura principale dell'economia uzbeka, ma la produzione era diminuita rispetto ai livelli dell'era sovietica a causa di problemi di gestione delle risorse idriche e della diversificazione agricola promossa dal governo, che ha puntato anche a sviluppare l'industria di trasformazione del cotone."
   ],
