   "id": "z843b2ecf",
   "sez": "mondo",
   "titolo": "MSF: i tagli ai finanziamenti lasciano 150.000 sfollati a rischio malattie in Sud Sudan",
   "orig": "MSF: Funding cuts leave 150,000 displaced people at risk of diseases in Bentiu and Malakal",
   "lead": "Secondo Medici Senza Frontiere, i tagli ai finanziamenti e il ritiro di organizzazioni umanitarie hanno lasciato circa 150.000 persone sfollate nei campi di Bentiu e Malakal, in Sud Sudan, esposte al rischio di colera e altre malattie legate alla scarsità di acqua potabile e servizi igienico-sanitari. L'organizzazione avverte che la riduzione dell'accesso a risorse di base aggrava le condizioni di vita già precarie nei due campi. Lo riferisce Radio Tamazuj.",
   "more": [
    "Il Sud Sudan ospita da anni centinaia di migliaia di persone sfollate a causa di conflitti interni e crisi climatiche. I campi di Bentiu e Malakal, nelle regioni di Unity e Upper Nile, dipendono fortemente dall'assistenza umanitaria internazionale, resa più fragile dalla recente riduzione dei finanziamenti globali destinati agli aiuti."
   ],
