   "id": "zb95e33b0",
   "sez": "mondo",
   "titolo": "La Guardia Civil perquisisce la casa di Ábalos a Valencia nel caso Koldo, sei arresti",
   "orig": "La UCO registra la casa de Ábalos en Valencia en un nuevo operativo del ‘caso Koldo’ con seis detenidos",
   "lead": "L'Unità Centrale Operativa della Guardia Civil spagnola ha perquisito l'abitazione dell'ex ministro José Luis Ábalos a Valencia nell'ambito di una nuova operazione del \"caso Koldo\", che ha portato a sei arresti, tra cui l'ex chauffeur del presidente Pedro Sánchez. Il giudice Ismael Moreno ha aperto mercoledì un procedimento separato e segreto dopo un rapporto della Guardia Civil, autorizzando perquisizioni anche a Madrid, Siviglia e Córdoba, e ha richiesto informazioni al gestore ferroviario pubblico Adif. In un audio diffuso dalla Cadena SER, l'ex assistente di Ábalos, Koldo García, ha affermato di aver concordato con l'avvocato del Partito Popolare un pagamento di un milione di euro in cambio di informazioni per far cadere Sánchez.",
   "more": [
    "Il \"caso Koldo\" riguarda un'inchiesta su presunte tangenti legate ad appalti pubblici durante la pandemia, che coinvolge l'ex ministro dei Trasporti José Luis Ábalos e il suo ex assistente Koldo García, considerati vicini all'ex presidente Pedro Sánchez. Lo scandalo è diventato uno dei principali fronti politici e giudiziari che indeboliscono il governo spagnolo negli ultimi anni."
   ],
