   "orig": "Interior Ministry employees will be allowed to work in the private sector outside their regular working hours, with their employer’s consent",
   "lead": "In Moldova, i dipendenti con status speciale del ministero degli Affari Interni potranno svolgere lavori retribuiti nel settore privato fuori dal loro orario di servizio, a condizione di ottenere il consenso del proprio datore di lavoro. La misura riguarda il personale con funzioni particolari all'interno del ministero e introduce una possibilità finora non prevista per questa categoria di dipendenti pubblici. Lo riferisce IPN.",
